        VoteHistoryViewBuilder(VoteRow vote) {
            this(vote, false, false);
        }

        VoteHistoryViewBuilder current(boolean current) {
            return new VoteHistoryViewBuilder(vote, current, counting);
        }

        VoteHistoryViewBuilder counting(boolean counting) {
            return new VoteHistoryViewBuilder(vote, current, counting);
        }

        ApiDtos.VoteHistoryView build() {
            return new ApiDtos.VoteHistoryView(vote.segmentId(), vote.language(), vote.stage(), vote.reviewer(),
                    vote.voteVersion(), vote.voteKey(), vote.decision(), vote.sourceVersion(),
                    vote.translationVersion(), vote.termVersion(), vote.policyVersion(), current, counting);
        }
    }
}

